world node {
    use aap:caps/types@0.1.0.{run-info, subscription-list};

    import aap:caps/state-read@0.1.0;

    export run: func(info: run-info) -> subscription-list;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn parse(raw: &str) -> Vec<String> {
    raw.split(|c: char| c.is_whitespace() || c == ',')
        .map(|t| t.trim_matches(|c: char| c == '[' || c == ']' || c == '"' || c == '\'' || c == ','))
        .filter(|t| !t.is_empty())
        .map(|t| t.to_string())
        .collect()
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in ["subscriptions", "urls", "feeds"] {
            if let Some(raw) = crate::aap::caps::state_read::get(key) {
                urls = parse(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }
        SubscriptionList { urls }
    }
}

export!(Node);
